import 'dart:async';
import 'package:flutter/material.dart';
import 'package:flutter_bloc/flutter_bloc.dart';
import 'package:intl/intl.dart';
void main()=>runApp(const ChatifyApp());
abstract class ChatRepository{Stream<List<Conversation>> watch();Future<void> send(String id,String text);}
class Conversation{const Conversation(this.id,this.name,this.preview,this.time,{this.unread=0,this.group=false,this.online=false});final String id,name,preview;final DateTime time;final int unread;final bool group,online;}
class Message{const Message(this.text,this.mine,this.at,{this.reply});final String text;final bool mine;final DateTime at;final Message? reply;}
class LocalRepository implements ChatRepository{final out=StreamController<List<Conversation>>.broadcast();final data=[Conversation('sara','Sara Ahmed','Sounds perfect, see you then!',DateTime.now(),unread:2,online:true),Conversation('team','Design team','Omar: The new prototype is ready',DateTime.now().subtract(const Duration(hours:1)),group:true),Conversation('mo','Mohamed Ali','Voice message',DateTime.now().subtract(const Duration(days:1)))];@override Stream<List<Conversation>> watch(){Future.microtask(()=>out.add(data));return out.stream;}@override Future<void> send(String id,String text)async{final i=data.indexWhere((x)=>x.id==id);if(i>=0){final x=data.removeAt(i);data.insert(0,Conversation(x.id,x.name,text,DateTime.now(),group:x.group,online:x.online));out.add(data);}}}
class ChatsCubit extends Cubit<List<Conversation>>{ChatsCubit(this.repo):super(const []){sub=repo.watch().listen(emit);}final ChatRepository repo;StreamSubscription? sub;@override Future<void> close(){sub?.cancel();return super.close();}}
class ChatifyApp extends StatelessWidget{const ChatifyApp({super.key});@override Widget build(BuildContext c)=>RepositoryProvider<ChatRepository>(create:(_)=>LocalRepository(),child:BlocProvider(create:(c)=>ChatsCubit(c.read()),child:MaterialApp(debugShowCheckedModeBanner:false,title:'Chatify',themeMode:ThemeMode.system,theme:_theme(Brightness.light),darkTheme:_theme(Brightness.dark),home:const Home())));}
ThemeData _theme(Brightness b){final s=ColorScheme.fromSeed(seedColor:const Color(0xff176b87),brightness:b);return ThemeData(useMaterial3:true,colorScheme:s,inputDecorationTheme:InputDecorationTheme(filled:true,fillColor:s.surfaceContainerHigh,border:OutlineInputBorder(borderRadius:BorderRadius.circular(18),borderSide:BorderSide.none)));}
class Home extends StatefulWidget{const Home({super.key});@override State<Home> createState()=>_HomeState();}class _HomeState extends State<Home>{int tab=0;@override Widget build(BuildContext c)=>Scaffold(body:[_chats(),const Calls(),const Settings()][tab],bottomNavigationBar:NavigationBar(selectedIndex:tab,onDestinationSelected:(v)=>setState(()=>tab=v),destinations:const[NavigationDestination(icon:Icon(Icons.chat_bubble_outline),selectedIcon:Icon(Icons.chat),label:'Chats'),NavigationDestination(icon:Icon(Icons.call_outlined),label:'Calls'),NavigationDestination(icon:Icon(Icons.settings_outlined),label:'Settings')]));Widget _chats()=>SafeArea(child:Column(children:[Padding(padding:const EdgeInsets.fromLTRB(20,15,12,8),child:Row(children:[Text('Chatify',style:Theme.of(context).textTheme.headlineMedium?.copyWith(fontWeight:FontWeight.bold)),const Spacer(),IconButton(onPressed:()=>showSearch(context:context,delegate:SearchChats()),icon:const Icon(Icons.search)),IconButton(onPressed:_newChat,icon:const Icon(Icons.edit_square))])),Expanded(child:BlocBuilder<ChatsCubit,List<Conversation>>(builder:(c,list){if(list.isEmpty)return const Center(child:CircularProgressIndicator());return ListView.separated(padding:const EdgeInsets.all(12),itemCount:list.length,separatorBuilder:(_,__)=>const Divider(indent:75),itemBuilder:(c,i){final x=list[i];return ListTile(contentPadding:const EdgeInsets.symmetric(vertical:4),leading:CircleAvatar(radius:27,child:Icon(x.group?Icons.groups:Icons.person)),title:Text(x.name,style:const TextStyle(fontWeight:FontWeight.bold)),subtitle:Text(x.preview,maxLines:1,overflow:TextOverflow.ellipsis),trailing:Column(mainAxisAlignment:MainAxisAlignment.center,children:[Text(DateFormat.Hm().format(x.time),style:Theme.of(c).textTheme.labelSmall),if(x.unread>0)Badge(label:Text('${x.unread}'))]),onTap:()=>Navigator.push(c,MaterialPageRoute(builder:(_)=>Chat(x))));}))]));void _newChat()=>showModalBottomSheet(context:context,showDragHandle:true,builder:(_)=>const SizedBox(height:170,child:Column(children:[ListTile(leading:Icon(Icons.group_add),title:Text('New group')),ListTile(leading:Icon(Icons.person_add),title:Text('New conversation'))])));}
class Chat extends StatefulWidget{const Chat(this.x,{super.key});final Conversation x;@override State<Chat> createState()=>_ChatState();}class _ChatState extends State<Chat>{final text=TextEditingController(),scroll=ScrollController();Message? reply;late List<Message> items;@override void initState(){super.initState();items=[Message('Hi! Are we still meeting this afternoon?',false,DateTime.now().subtract(const Duration(minutes:16))),Message('Absolutely. I booked the table for 4.',true,DateTime.now().subtract(const Duration(minutes:12))),Message('Sounds perfect, see you then!',false,DateTime.now().subtract(const Duration(minutes:2)))];}@override void dispose(){text.dispose();scroll.dispose();super.dispose();}void send(){if(text.text.trim().isEmpty)return;setState((){items.add(Message(text.text,true,DateTime.now(),reply:reply));text.clear();reply=null;});context.read<ChatRepository>().send(widget.x.id,items.last.text);}@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:Row(children:[CircleAvatar(child:Icon(widget.x.group?Icons.groups:Icons.person)),const SizedBox(width:9),Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(widget.x.name,style:const TextStyle(fontSize:16,fontWeight:FontWeight.bold)),Text(widget.x.online?'online':'last seen recently',style:Theme.of(c).textTheme.labelSmall)])),const Spacer(),IconButton(onPressed:()=>_call(false),icon:const Icon(Icons.call)),IconButton(onPressed:()=>_call(true),icon:const Icon(Icons.videocam))])),body:Column(children:[Expanded(child:ListView.builder(controller:scroll,padding:const EdgeInsets.all(16),itemCount:items.length,itemBuilder:(_,i)=>_bubble(items[i]))),if(reply!=null)Container(color:Theme.of(c).colorScheme.surfaceContainerHigh,padding:const EdgeInsets.symmetric(horizontal:16),child:Row(children:[const Icon(Icons.reply),const SizedBox(width:8),Expanded(child:Text('Replying to ${reply!.text}',maxLines:1)),IconButton(onPressed:()=>setState(()=>reply=null),icon:const Icon(Icons.close))])),SafeArea(top:false,child:Padding(padding:const EdgeInsets.all(10),child:Row(children:[IconButton(onPressed:_attachments,icon:const Icon(Icons.add_circle_outline)),Expanded(child:TextField(controller:text,onSubmitted:(_)=>send(),maxLines:4,minLines:1,decoration:const InputDecoration(hintText:'Message'))),IconButton(onPressed:send,icon:const Icon(Icons.send))])))]));Widget _bubble(Message m)=>Align(alignment:m.mine?Alignment.centerRight:Alignment.centerLeft,child:GestureDetector(onLongPress:()=>setState(()=>reply=m),child:Container(constraints:const BoxConstraints(maxWidth:310),margin:const EdgeInsets.only(bottom:9),padding:const EdgeInsets.all(12),decoration:BoxDecoration(color:m.mine?Theme.of(context).colorScheme.primaryContainer:Theme.of(context).colorScheme.surfaceContainerHigh,borderRadius:BorderRadius.circular(16)),child:Column(crossAxisAlignment:CrossAxisAlignment.end,children:[if(m.reply!=null)Align(alignment:Alignment.centerLeft,child:Text(m.reply!.text,maxLines:1,overflow:TextOverflow.ellipsis,style:Theme.of(context).textTheme.labelSmall)),Align(alignment:Alignment.centerLeft,child:Text(m.text)),Text(DateFormat.Hm().format(m.at),style:Theme.of(context).textTheme.labelSmall)]))));void _attachments()=>showModalBottomSheet(context:context,showDragHandle:true,builder:(_)=>const SizedBox(height:150,child:Row(mainAxisAlignment:MainAxisAlignment.spaceEvenly,children:[_Attach(Icons.photo,'Photo'),_Attach(Icons.videocam,'Video'),_Attach(Icons.description,'Document'),_Attach(Icons.mic,'Voice')])));void _call(bool video)=>Navigator.push(context,MaterialPageRoute(builder:(_)=>Call(widget.x.name,video)));}
class _Attach extends StatelessWidget{const _Attach(this.i,this.s);final IconData i;final String s;@override Widget build(BuildContext c)=>Column(mainAxisSize:MainAxisSize.min,children:[CircleAvatar(radius:26,child:Icon(i)),const SizedBox(height:7),Text(s)]);}
class Call extends StatelessWidget{const Call(this.name,this.video,{super.key});final String name;final bool video;@override Widget build(BuildContext c)=>Scaffold(backgroundColor:Colors.black,body:SafeArea(child:Column(children:[const Spacer(),const CircleAvatar(radius:56,child:Icon(Icons.person,size:65)),const SizedBox(height:20),Text(name,style:const TextStyle(color:Colors.white,fontSize:28,fontWeight:FontWeight.bold)),const SizedBox(height:8),const Text('Connecting securely…',style:TextStyle(color:Colors.white70)),const Spacer(),Row(mainAxisAlignment:MainAxisAlignment.spaceEvenly,children:[const FloatingActionButton(onPressed:null,child:Icon(Icons.mic)),if(video)const FloatingActionButton(onPressed:null,child:Icon(Icons.videocam)),FloatingActionButton(backgroundColor:Colors.red,onPressed:()=>Navigator.pop(c),child:const Icon(Icons.call_end))]),const SizedBox(height:34)])));}
class Calls extends StatelessWidget{const Calls({super.key});@override Widget build(BuildContext c)=>SafeArea(child:ListView(children:[Padding(padding:const EdgeInsets.all(20),child:Text('Calls',style:Theme.of(c).textTheme.headlineMedium?.copyWith(fontWeight:FontWeight.bold))),const ListTile(leading:CircleAvatar(child:Icon(Icons.person)),title:Text('Sara Ahmed'),subtitle:Text('Today, 10:42 · Outgoing'),trailing:Icon(Icons.call,color:Colors.green))]));}class Settings extends StatelessWidget{const Settings({super.key});@override Widget build(BuildContext c)=>SafeArea(child:ListView(children:[Padding(padding:const EdgeInsets.all(20),child:Text('Settings',style:Theme.of(c).textTheme.headlineMedium?.copyWith(fontWeight:FontWeight.bold))),const ListTile(leading:CircleAvatar(radius:28,child:Icon(Icons.person)),title:Text('Your profile'),subtitle:Text('Set display name, username and bio')),const Divider(),const ListTile(leading:Icon(Icons.notifications_outlined),title:Text('Notifications')),const ListTile(leading:Icon(Icons.dark_mode_outlined),title:Text('Appearance'),subtitle:Text('System default')),const ListTile(leading:Icon(Icons.language),title:Text('Language'),subtitle:Text('English · العربية')),const ListTile(leading:Icon(Icons.lock_outline),title:Text('Privacy and security'))]));}class SearchChats extends SearchDelegate{@override List<Widget>? buildActions(c)=>[IconButton(onPressed:()=>query='',icon:const Icon(Icons.clear))];@override Widget? buildLeading(c)=>IconButton(onPressed:()=>close(c,null),icon:const Icon(Icons.arrow_back));@override Widget buildResults(c)=>buildSuggestions(c);@override Widget buildSuggestions(c){final names=['Sara Ahmed','Design team','Mohamed Ali'].where((x)=>x.toLowerCase().contains(query.toLowerCase()));return ListView(children:names.map((x)=>ListTile(title:Text(x),leading:const CircleAvatar(child:Icon(Icons.person)))).toList());}}
